describe('Login Form Validation - Empty Fields', () => {
  beforeEach(() => {
    cy.visit('/login');
    cy.get('form').should('be.visible');
  });

  it('should prevent form submission when both email and password fields are empty', () => {
    cy.get('button[type="submit"]').click();

    cy.get('form').should('exist');
    cy.url().should('include', '/login');

    cy.get('[data-testid="email-error"]').should('be.visible').and('contain', 'Email is required');
    cy.get('[data-testid="password-error"]').should('be.visible').and('contain', 'Password is required');
  });

  it('should prevent form submission when only email field is empty', () => {
    cy.get('input[name="password"]').type('validPassword123');
    cy.get('button[type="submit"]').click();

    cy.get('[data-testid="email-error"]').should('be.visible').and('contain', 'Email is required');
    cy.get('[data-testid="password-error"]').should('not.exist');
    cy.url().should('include', '/login');
  });

  it('should prevent form submission when only password field is empty', () => {
    cy.get('input[name="email"]').type('user@example.com');
    cy.get('button[type="submit"]').click();

    cy.get('[data-testid="password-error"]').should('be.visible').and('contain', 'Password is required');
    cy.get('[data-testid="email-error"]').should('not.exist');
    cy.url().should('include', '/login');
  });

  it('should enable form submission when both fields are populated', () => {
    cy.get('input[name="email"]').type('user@example.com');
    cy.get('input[name="password"]').type('validPassword123');

    cy.get('button[type="submit"]').should('not.be.disabled');
    cy.get('[data-testid="email-error"]').should('not.exist');
    cy.get('[data-testid="password-error"]').should('not.exist');
  });

  it('should clear error messages when user fills in previously empty fields', () => {
    cy.get('button[type="submit"]').click();
    cy.get('[data-testid="email-error"]').should('be.visible');
    cy.get('[data-testid="password-error"]').should('be.visible');

    cy.get('input[name="email"]').type('user@example.com');
    cy.get('[data-testid="email-error"]').should('not.exist');

    cy.get('input[name="password"]').type('validPassword123');
    cy.get('[data-testid="password-error"]').should('not.exist');
  });

  it('should handle whitespace-only input as empty field', () => {
    cy.get('input[name="email"]').type('   ');
    cy.get('input[name="password"]').type('   ');
    cy.get('button[type="submit"]').click();

    cy.get('[data-testid="email-error"]').should('be.visible');
    cy.get('[data-testid="password-error"]').should('be.visible');
    cy.url().should('include', '/login');
  });
});
